package com.tencent.weknora.security;
import com.fasterxml.jackson.databind.*;
import java.nio.file.*;import java.time.*;import java.util.*;import javax.sql.DataSource;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.io.FileSystemResource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.init.ScriptUtils;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"weknora.jwt-secret=isolated-invitation-http-secret","weknora.bridge.enabled=false","logging.level.root=WARN","debug=false","FRONTEND_BASE_URL=https://frontend.example///"})
@AutoConfigureMockMvc @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class TenantInvitationHttpIntegrationTest {
    private static final Path DATABASE;static{try{DATABASE=Files.createTempFile("weknora-invitation-http-",".db");DATABASE.toFile().deleteOnExit();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
    @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:sqlite:"+DATABASE+"?busy_timeout=10000");p.add("spring.datasource.driver-class-name",()->"org.sqlite.JDBC");}
    @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired DataSource datasource;@Autowired JwtCodec jwt;@Autowired AuthRepository repository;@Autowired ObjectMapper json;
    private String owner,invitee,other;
    @BeforeAll void schema()throws Exception{try(var c=datasource.getConnection()){for(String script:List.of("000000_init.up.sql","000005_messages_attachments_and_invitation_fields.up.sql","000007_system_admin_and_settings.up.sql"))ScriptUtils.executeSqlScript(c,new FileSystemResource("../migrations/sqlite/"+script));}}
    @BeforeEach void reset(){for(String table:List.of("tenant_invitations","audit_logs","auth_tokens","tenant_api_keys","tenant_members","users","tenants","system_settings"))jdbc.update("DELETE FROM "+table);jdbc.update("INSERT INTO tenants(id,name,business) VALUES(7,'Workspace','test'),(8,'Other','test')");jdbc.update("INSERT INTO users(id,username,email,password_hash,tenant_id) VALUES('owner','Owner','owner@example.com','unused',7),('invitee','Invitee','invitee@example.com','unused',NULL),('other','Other','other@example.com','unused',NULL)");jdbc.update("INSERT INTO tenant_members(user_id,tenant_id,role,status) VALUES('owner',7,'owner','active')");owner=token("owner",7);invitee=token("invitee",0);other=token("other",0);}
    @Test void tenantlessInboxAcceptAdoptsWorkspaceAndDuplicateCannotEmitAnotherAudit()throws Exception{var inv=direct();long id=inv.path("id").asLong();assertEquals("invitee@example.com",inv.path("invitee_email").asText());assertFalse(inv.has("token"));assertEquals(0,count("tenant_members","user_id='invitee'"));mvc.perform(get("/api/v1/me/invitations/pending-count").header("Authorization","Bearer "+invitee)).andExpect(status().isOk()).andExpect(jsonPath("$.data.pending_count").value(1));mvc.perform(get("/api/v1/me/invitations").header("Authorization","Bearer "+invitee)).andExpect(status().isOk()).andExpect(jsonPath("$.data.invitations[0].tenant_name").value("Workspace"));mvc.perform(post("/api/v1/me/invitations/"+id+"/accept").header("Authorization","Bearer "+invitee)).andExpect(status().isOk()).andExpect(jsonPath("$.data.membership.role").value("contributor"));assertEquals(7,jdbc.queryForObject("SELECT tenant_id FROM users WHERE id='invitee'",Integer.class));assertEquals(3,count("audit_logs","1=1"));mvc.perform(post("/api/v1/me/invitations/"+id+"/accept").header("Authorization","Bearer "+invitee)).andExpect(status().isConflict());assertEquals(3,count("audit_logs","1=1"));}
    @Test void wrongInviteeDeclineExpiredAndRevokeEnforceInvitationStateAndTenantBoundary()throws Exception{long id=direct().path("id").asLong();mvc.perform(post("/api/v1/me/invitations/"+id+"/accept").header("Authorization","Bearer "+other)).andExpect(status().isForbidden());mvc.perform(post("/api/v1/me/invitations/"+id+"/decline").header("Authorization","Bearer "+invitee)).andExpect(status().isOk());assertEquals("declined",jdbc.queryForObject("SELECT status FROM tenant_invitations WHERE id=?",String.class,id));long second=direct().path("id").asLong();jdbc.update("UPDATE tenant_invitations SET tenant_id=8 WHERE id=?",second);mvc.perform(delete("/api/v1/tenants/7/invitations/"+second).header("Authorization","Bearer "+owner)).andExpect(status().isNotFound());jdbc.update("UPDATE tenant_invitations SET tenant_id=7,expires_at=? WHERE id=?",repository.timestampParameter(Instant.now().minusSeconds(10)),second);mvc.perform(post("/api/v1/me/invitations/"+second+"/accept").header("Authorization","Bearer "+invitee)).andExpect(status().isConflict());assertEquals("expired",jdbc.queryForObject("SELECT status FROM tenant_invitations WHERE id=?",String.class,second));}
    @Test void publicLookupTokenJoinIsMultiuseReconcilesDirectInvitationAndNeverDowngradesExistingRole()throws Exception{long direct=direct().path("id").asLong();var share=link();String token=share.path("invite_url").asText().split("token=")[1];assertEquals(43,token.length());assertTrue(share.path("invite_url").asText().startsWith("https://frontend.example/register"));mvc.perform(post("/api/v1/auth/invitations/lookup").contentType("application/json").content(json.writeValueAsString(Map.of("token",token)))).andExpect(status().isOk()).andExpect(jsonPath("$.data.tenant_name").value("Workspace"));join(invitee,token);join(other,token);join(invitee,token);assertEquals(2,jdbc.queryForObject("SELECT accepted_count FROM tenant_invitations WHERE id=?",Integer.class,share.path("id").asLong()));assertEquals("pending",jdbc.queryForObject("SELECT status FROM tenant_invitations WHERE id=?",String.class,share.path("id").asLong()));assertEquals("accepted",jdbc.queryForObject("SELECT status FROM tenant_invitations WHERE id=?",String.class,direct));assertEquals("admin",repository.role("invitee",7));}
    @Test void viewerAndLimitedMachineCanListMetadataButCannotCopyLinkOrAssignOwnerAndCannotUseInbox()throws Exception{link();jdbc.update("UPDATE tenant_members SET role='viewer' WHERE user_id='owner'");mvc.perform(get("/api/v1/tenants/7/invitations").header("Authorization","Bearer "+owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.invitations[0].invite_url").doesNotExist());String raw="sk-invite-http-test";jdbc.update("INSERT INTO tenant_api_keys(tenant_id,name,key_hash,api_key,full_access,capabilities) VALUES(7,'Machine',?,?,false,'[\"manage_members\"]')",AuthFilter.hashApiKey(raw),raw);mvc.perform(get("/api/v1/tenants/7/invitations").header("X-API-Key",raw)).andExpect(status().isOk()).andExpect(jsonPath("$.data.invitations[0].invite_url").doesNotExist());mvc.perform(post("/api/v1/tenants/7/invite-links").header("X-API-Key",raw).contentType("application/json").content("{\"role\":\"owner\"}")).andExpect(status().isForbidden());mvc.perform(get("/api/v1/me/invitations").header("X-API-Key",raw)).andExpect(status().isForbidden());}
    @Test void autoAcceptImmediatelyCreatesMembershipAdoptsHomeAndClosesPendingWithoutNewInvitation()throws Exception{long id=direct().path("id").asLong();jdbc.update("INSERT INTO system_settings(key,value,value_type,category,last_modified_by) VALUES('tenant.auto_accept_invitation','true','bool','tenant','owner')");var response=mvc.perform(post("/api/v1/tenants/7/invitations").header("Authorization","Bearer "+owner).contentType("application/json").content("{\"email\":\"invitee@example.com\",\"role\":\"viewer\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.data.user_id").value("invitee")).andReturn().getResponse();assertFalse(json.readTree(response.getContentAsString()).path("data").has("id"));assertEquals(1,count("tenant_invitations","1=1"));assertEquals("accepted",jdbc.queryForObject("SELECT status FROM tenant_invitations WHERE id=?",String.class,id));assertEquals(7,jdbc.queryForObject("SELECT tenant_id FROM users WHERE id='invitee'",Integer.class));}
    @Test void acceptedInvitationStaysCommittedOnMembershipFailureAndRevokedUnknownTokensCollapseToGone()throws Exception{long id=direct().path("id").asLong();jdbc.execute("CREATE TRIGGER invite_member_fail BEFORE INSERT ON tenant_members BEGIN SELECT RAISE(ABORT,'isolated member failure'); END");try{mvc.perform(post("/api/v1/me/invitations/"+id+"/accept").header("Authorization","Bearer "+invitee)).andExpect(status().isInternalServerError());assertEquals("accepted",jdbc.queryForObject("SELECT status FROM tenant_invitations WHERE id=?",String.class,id));assertEquals(0,count("tenant_members","user_id='invitee'"));}finally{jdbc.execute("DROP TRIGGER invite_member_fail");}var share=link();String token=share.path("invite_url").asText().split("token=")[1];mvc.perform(delete("/api/v1/tenants/7/invitations/"+share.path("id").asLong()).header("Authorization","Bearer "+owner)).andExpect(status().isOk());for(String raw:List.of(token,"missing"))mvc.perform(post("/api/v1/auth/invitations/lookup").contentType("application/json").content(json.writeValueAsString(Map.of("token",raw)))).andExpect(status().isGone()).andExpect(jsonPath("$.error.message").value("invitation link is invalid or has been revoked"));}
    private JsonNode direct()throws Exception{return json.readTree(mvc.perform(post("/api/v1/tenants/7/invitations").header("Authorization","Bearer "+owner).contentType("application/json").content("{\"email\":\"invitee@example.com\",\"role\":\"contributor\",\"message\":\"note\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString()).path("data");}
    private JsonNode link()throws Exception{return json.readTree(mvc.perform(post("/api/v1/tenants/7/invite-links").header("Authorization","Bearer "+owner).contentType("application/json").content("{\"role\":\"admin\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString()).path("data");}
    private void join(String access,String token)throws Exception{mvc.perform(post("/api/v1/me/invitations/accept-by-token").header("Authorization","Bearer "+access).contentType("application/json").content(json.writeValueAsString(Map.of("token",token)))).andExpect(status().isOk());}
    private int count(String table,String condition){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE "+condition,Integer.class);}
    private String token(String user,long tenant){String value=jwt.sign(Map.of("user_id",user,"email",user+"@example.com","tenant_id",tenant,"type","access","exp",Instant.now().plusSeconds(3600).getEpochSecond()));repository.storeToken(user,value,"access_token",Instant.now().plusSeconds(3600));return value;}
}
